SPECTRAL = "e2000fs_budget_spectral"
SUPPORTED = tuple(sorted([*RECIPES, SPECTRAL]))
UNSUPPORTED = {
    "e2000fs_budget_complexity": "Expanding-window complexity and group mass require verified missing-label accounting.",
    "e2000fs_budget_covshift": "Classifier training includes pre-cutoff unlabelled origins outside fit masks; requires separate context grid.",
    "e2000fs_budget_primaldual": "Prior-period risk budgets require verified masked calibration and dual updates.",
    "e2000fs_feat30_agnostic_v2_context": "Partially observed block event labels require an explicit known/unknown event policy.",
    "e2000fs_feat30_agnostic_v2_event": "Nonlinear trajectory parameters require a verified fit on partially observed curves.",
    "e2000fs_feat30_probtraj": "Leaf-weighted donor trajectories require per-horizon observed-donor normalization.",
}


def kernel(experiment, threads=1, smoke=False):
    env = {"__name__": "frozen_advanced_recipe"}
    exec(compile(RECIPES[experiment]["helpers"], f"<frozen:{experiment}>", "exec"), env)
    env["PARAMS"] = dict(env["PARAMS"], n_jobs=threads)
    env["params"] = dict(env["PARAMS"], n_estimators=3 if smoke else env["PARAMS"]["n_estimators"])
    env["rounds"], env["smoke"] = env["params"]["n_estimators"], smoke
    if experiment.endswith("smooth_error_tail"):
        env["params"]["objective"] = env["smooth_tail"]
    return env


def selected_names(features):
    return {key: [n for n in values if n in features] for key, values in BASE_NAMES.items()}


def mapped(name):
    return name.replace("ch_ch_", "suvi_", 1) if name.startswith("ch_ch_") else name


def speed_history(data, origins):
    speed = pd.read_parquet(data, columns=["origin", "v_lag0"], filters=[("h", "==", 1)])
    speed["origin"] = pd.to_datetime(speed.origin, utc=True)
    if (speed.groupby("origin").v_lag0.nunique(dropna=False) > 1).any():
        raise ValueError("train/query speed snapshots disagree")
    speed = speed.drop_duplicates("origin").sort_values("origin").set_index("origin").v_lag0
    t = origins.asi8[:, None] + np.arange(-23, 1)[None, :] * 3_600_000_000_000
    return speed.reindex(pd.DatetimeIndex(t.ravel(), tz="UTC")).to_numpy(np.float64).reshape(-1, 24)


def load_grid(data, period, names, training):
    filters = [(f"fit_{period}", "==", True)] if training else [("set", "==", "query"), ("period", "==", period)]
    constant = pd.read_parquet(data, columns=["origin", *[mapped(c) for c in names["constant"]]],
                               filters=[*filters, ("h", "==", 1)]).sort_values("origin", kind="stable")
    origins = pd.DatetimeIndex(pd.to_datetime(constant.origin, utc=True))
    if origins.has_duplicates:
        raise ValueError("duplicate input origins")
    columns = ["origin", "h", *names["varying"]] + (["y"] if training else [])
    rows = pd.read_parquet(data, columns=columns, filters=filters).sort_values(["origin", "h"], kind="stable")
    if len(rows) != len(origins) * H or not np.array_equal(rows.h.to_numpy().reshape(-1, H), np.broadcast_to(np.arange(1, H + 1), (len(origins), H))):
        raise ValueError("incomplete origin/horizon grid")
    if not origins.equals(pd.DatetimeIndex(pd.to_datetime(rows.origin.iloc[::H], utc=True))):
        raise ValueError("constant and varying grids disagree")
    if training and not (origins + pd.Timedelta(hours=144) <= pd.Timestamp(CUTOFFS[period], tz="UTC")).all():
        raise ValueError("training cutoff violated")
    grid = {"origins": origins, "C": constant[[mapped(c) for c in names["constant"]]].to_numpy(np.float32),
            "E": rows[names["varying"]].to_numpy(np.float32).reshape(len(origins), H, len(names["varying"]))}
    return grid, rows.y.to_numpy(np.float64).reshape(len(origins), H) if training else None


def design(grid, start):
    return np.hstack([grid["C"], grid["E"][:, start:start + 24].reshape(len(grid["C"]), -1)]).astype(np.float32)


def prepare_context(experiment, env, train, query, y, names, past=None, query_past=None):
    context = dict(X={s: design(train, s) for s in (0, 24, 48)},
                   Xq={s: design(query, s) for s in (0, 24, 48)}, y=y,
                   origins=train["origins"], names=names)
    all_fit = np.arange(len(y))
    if experiment.endswith("transfer_center"):
        mask = np.array([n == "v_lag0" or n.startswith("ace_speed") or n in ("rec26", "rec27", "rec28", "rec_mean")
                         for n in names["constant"] + names["varying"] * 24])
        context["X"], context["anchor"] = env["center"](context["X"], past, mask)
        context["Xq"], context["query_anchor"] = env["center"](context["Xq"], query_past, mask)
        if not np.isfinite(context["query_anchor"]).all():
            raise ValueError("query speed history has no complete causal centering window")
    elif experiment.endswith("hyper_gain"):
        context["anchor"], context["gain"] = env["decoder"](train, names)
        context["query_anchor"], context["query_gain"] = env["decoder"](query, names)
        if not np.isfinite(context["query_anchor"]).all():
            raise ValueError("query anchor is missing")
    elif experiment.endswith("transfer_recency"):
        context["all_weights"] = env["recency_weights"](train["origins"], all_fit)
    elif experiment.endswith("transfer_recent_window"):
        age = np.asarray((train["origins"].max() - train["origins"]) / pd.Timedelta(days=1))
        all_fit = all_fit[age <= 365]
    elif experiment.endswith("mc_calibration"):
        context["all_prefix"], context["all_calibration"] = env["calibration_split"](train["origins"], all_fit)
    context["all_fit"] = all_fit
    return context


def horizon_inputs(experiment, context, h):
    valid = np.isfinite(context["y"][:, h])
    if "anchor" in context:
        valid &= np.isfinite(context["anchor"])
    fit = context["all_fit"][valid[context["all_fit"]]]
    if len(fit) < 2:
        raise ValueError(f"h{h + 1}: insufficient observed training targets")
    env = {**context, "fit": fit, "h": h}
    if "all_weights" in context:
        env["weights"] = context["all_weights"][fit]
    if "all_prefix" in context:
        env["prefix"] = context["all_prefix"][valid[context["all_prefix"]]]
        env["calibration"] = context["all_calibration"][valid[context["all_calibration"]]]
        if len(env["prefix"]) < 2 or len(env["calibration"]) < 2:
            raise ValueError(f"h{h + 1}: insufficient observed prior calibration targets")
    return env


def save_models(env, out):
    """Persist actual fitted native boosters and required centering/scaling state."""
    out = Path(out)
    saved = []
    for name in ("model", "base", "head", "pilot"):
        model = env.get(name)
        if isinstance(model, lgb.LGBMRegressor):
            model.booster_.save_model(out / f"{name}.txt")
            saved.append(f"{name}.txt")
        elif isinstance(model, lgb.Booster):
            model.save_model(out / f"{name}.txt")
            saved.append(f"{name}.txt")
    for i, booster in enumerate(env.get("boosters", [])):
        booster.save_model(out / f"distribution_{i}.txt")
        saved.append(f"distribution_{i}.txt")
    for i, teacher in enumerate(env.get("_teachers", [])):
        teacher.booster_.save_model(out / f"teacher_{i}.txt")
        saved.append(f"teacher_{i}.txt")
    state = {name: np.asarray(env[name]) for name in ("offset", "offsets", "mean", "scale") if name in env}
    if state:
        np.savez_compressed(out / "transform_state.npz", **state)
    if not saved:
        raise ValueError("recipe produced no persisted fitted model")
    return saved


def fit_horizon(experiment, context, h, out, threads=1, smoke=False):
    env = kernel(experiment, threads, smoke)
    env.update(horizon_inputs(experiment, context, h))
    out = Path(out)
    out.mkdir(parents=True, exist_ok=True)
    env["out"] = out
    env["_teachers"] = []
    if "fit_teacher" in env:
        original_teacher = env["fit_teacher"]

        def save_teacher(*args, **kwargs):
            teacher = original_teacher(*args, **kwargs)
            env["_teachers"].append(teacher)
            return teacher
        env["fit_teacher"] = save_teacher
    # Only these resource controls differ from the frozen per-horizon statements.
    fit_code = RECIPES[experiment]["fit"].replace("num_threads=2", "num_threads=threads")
    predict_code = RECIPES[experiment]["predict"].replace("num_threads=2", "num_threads=threads")
    env["threads"] = threads
    query_setup = ""
    if experiment.endswith("mc_calibration"):
        fit_code, query_setup = fit_code.rsplit("\npq =", 1)
        query_setup = "pq =" + query_setup
    began = time.perf_counter()
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", message="X does not have valid feature names", category=UserWarning)
        exec(compile(fit_code, f"<fit:{experiment}>", "exec"), env)
        fit_seconds = time.perf_counter() - began
        began = time.perf_counter()
        if query_setup:
            exec(query_setup, env)
        prediction = np.asarray(eval(compile(predict_code, f"<predict:{experiment}>", "eval"), env), np.float64)
        inference_seconds = time.perf_counter() - began
    if not np.isfinite(prediction).all():
        raise ValueError(f"{experiment} h{h + 1}: nonfinite forecast")
    saved = save_models(env, out)
    report = {"horizon": h + 1, "observed_training_rows": len(env["fit"]),
              "fit_seconds": fit_seconds, "inference_seconds": inference_seconds, "models": saved}
    if "prefix" in env:
        report.update(prefix_rows=len(env["prefix"]), calibration_rows=len(env["calibration"]))
    (out / "metadata.json").write_text(json.dumps(report, indent=2) + "\n")
    return prediction, report


def spectral_objective(target):
    observed = np.isfinite(target)
    raw = np.where(target >= 550., 4., 1.) * observed
    weights = raw / (raw.sum(0) / observed.sum(0))

    def objective(prediction, matrix):
        prediction = np.asarray(prediction).reshape(target.shape)
        error = np.where(observed, prediction - np.nan_to_num(target), 0.)
        z = np.fft.fft(error, axis=1, norm="ortho")
        rho = 1 / np.sqrt(1 + abs(z) ** 2 / 50. ** 2)
        gradient = (error * weights + .10 * np.fft.ifft(z * rho, axis=1, norm="ortho").real) * observed
        return gradient.astype(np.float32), ((weights + .10) * observed).astype(np.float32)
    return objective


def spectral_parameters(threads):
    return dict(max_depth=3, learning_rate=.03, subsample=.8, colsample_bytree=.7,
                  min_child_weight=20, reg_lambda=5, objective="reg:squarederror", tree_method="hist",
                  device="cpu", eval_metric="rmse", multi_strategy="multi_output_tree", nthread=threads, seed=42, num_target=24)


def fit_spectral(train, query, y, out, threads, smoke):
    predictions = np.empty((len(query["C"]), H), dtype=np.float64)
    reports = []
    params = spectral_parameters(threads)
    for block, start in enumerate((0, 24, 48)):
        target = y[:, start:start + 24]
        keep = np.isfinite(target).any(axis=1)
        target = target[keep]
        if not np.isfinite(target).any(axis=0).all():
            raise ValueError("spectral output has no observed training targets")
        matrix = xgb.DMatrix(design(train, start)[keep], label=np.nan_to_num(target).astype(np.float32), nthread=threads)
        began = time.perf_counter()
        model = xgb.train(dict(params, base_score=float(np.nanmean(target))), matrix,
                          num_boost_round=2 if smoke else 900, obj=spectral_objective(target))
        fit_seconds = time.perf_counter() - began
        model.save_model(Path(out) / f"block{block}.ubj")
        xq = design(query, start)
        began = time.perf_counter()
        predictions[:, start:start + 24] = np.clip(model.inplace_predict(xq), 1, 3000)
        inference_seconds = time.perf_counter() - began
        reports.append({"block": block, "fit_seconds": fit_seconds, "inference_seconds": inference_seconds,
                        "observed_training_targets": int(np.isfinite(target).sum())})
    return predictions, reports


def run_period(experiment, data, out, period, threads=1, smoke=False):
    if experiment not in SUPPORTED:
        raise ValueError(UNSUPPORTED.get(experiment, "unknown experiment"))
    out = Path(out)
    out.mkdir(parents=True, exist_ok=True)
    start = time.perf_counter()
    template = kernel("e2000fs_feat30_transfer_recency" if experiment == SPECTRAL else experiment, threads, smoke)
    names = selected_names(template["FEATURES"])
    train, y = load_grid(data, period, names, True)
    query, _ = load_grid(data, period, names, False)
    if len(query["origins"]) != QUERY_COUNTS[period]:
        raise ValueError("unexpected query period grid")
    if smoke:
        keep = np.linspace(0, len(y) - 1, min(len(y), 512)).astype(int)
        train = {k: v[keep] for k, v in train.items()}
        y = y[keep]
        query = {k: v[:8] for k, v in query.items()}
    work = out / f"{period}_models"
    work.mkdir(parents=True, exist_ok=True)
    if experiment == SPECTRAL:
        predictions, reports = fit_spectral(train, query, y, work, threads, smoke)
    else:
        past = speed_history(data, train["origins"]) if experiment.endswith("transfer_center") else None
        query_past = speed_history(data, query["origins"]) if past is not None else None
        context = prepare_context(experiment, template, train, query, y, names, past, query_past)
        predictions = np.empty((len(query["origins"]), H), np.float64)
        reports = []
        for h in range(H):
            predictions[:, h], report = fit_horizon(experiment, context, h, work / f"h{h + 1:02}", threads, smoke)
            reports.append(report)
            print(json.dumps({"experiment": experiment, "period": period, **report}), flush=True)
    if not np.isfinite(predictions).all():
        raise ValueError("nonfinite predictions")
    np.savez_compressed(out / f"{period}_predictions.npz", pred=predictions, origins=query["origins"].asi8)
    revision = subprocess.run(["git", "rev-parse", "HEAD"], text=True, capture_output=True, check=False)
    report = {"experiment": experiment, "period": period, "smoke": smoke, "data": str(Path(data).resolve()),
              "data_bytes": Path(data).stat().st_size, "data_mtime_ns": Path(data).stat().st_mtime_ns,
              "git_commit": revision.stdout.strip() if revision.returncode == 0 else None,
              "training_cutoff": CUTOFFS[period], "maturity_hours": 144, "seed": 42,
              "features": names, "mapped_constant_features": [mapped(c) for c in names["constant"]],
              "block_feature_count": len(names["constant"]) + 24 * len(names["varying"]),
              "train_origins": len(y), "train_start": str(train["origins"].min()), "train_end": str(train["origins"].max()),
              "query_origins": len(predictions), "query_start": str(query["origins"].min()), "query_end": str(query["origins"].max()),
              "target_policy": "Each scalar horizon excludes missing labels before fitting/calibration. Spectral loss masks missing error coordinates and gradients.",
              "parameters": template["PARAMS"] if experiment != SPECTRAL else {**spectral_parameters(threads), "rounds": 2 if smoke else 900, "coefficient": .10, "scale": 50., "point4_threshold": 550.},
              "inference_seconds_per_fold": sum(r["inference_seconds"] for r in reports) / len(predictions),
              "end_to_end_seconds": time.perf_counter() - start,
              "versions": {"python": platform.python_version(), "numpy": np.__version__, "pandas": pd.__version__, "lightgbm": lgb.__version__, "xgboost": xgb.__version__},
              "fits": reports}
    (out / f"{period}_metadata.json").write_text(json.dumps(report, indent=2) + "\n")
    return report


def merge(out):
    out = Path(out)
    frames = []
    for period in CUTOFFS:
        z = np.load(out / f"{period}_predictions.npz")
        origins = pd.DatetimeIndex(z["origins"], tz="UTC")
        pred = z["pred"]
        if len(origins) != QUERY_COUNTS[period] or pred.shape != (len(origins), H) or not np.isfinite(pred).all():
            raise ValueError(f"incomplete full predictions for {period}")
        frames.append(pd.DataFrame({"origin_last_input_utc": np.repeat(origins.strftime("%Y-%m-%dT%H:%M:%SZ"), H),
                                    "horizon_hours": np.tile(np.arange(1, H + 1), len(origins)), "pred_kms": pred.ravel()}))
    result = pd.concat(frames, ignore_index=True)
    if result.duplicated(["origin_last_input_utc", "horizon_hours"]).any():
        raise ValueError("duplicate prediction keys")
    result.to_parquet(out / "predictions.parquet", index=False)
    return len(result)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--experiment", choices=SUPPORTED, required=True)
    parser.add_argument("--data", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--threads", type=int, default=1)
    parser.add_argument("--period", choices=list(CUTOFFS))
    parser.add_argument("--smoke", action="store_true")
    parser.add_argument("--merge", action="store_true")
    args = parser.parse_args()
    if args.threads < 1:
        parser.error("threads must be positive")
    if args.merge:
        print(json.dumps({"prediction_rows": merge(args.out)}))
        return
    for period in [args.period] if args.period else (["F1"] if args.smoke else list(CUTOFFS)):
        report = run_period(args.experiment, args.data, args.out, period, args.threads, args.smoke)
        print(json.dumps({k: report[k] for k in ("experiment", "period", "train_origins", "query_origins", "end_to_end_seconds")}))
    if not args.period and not args.smoke:
        print(json.dumps({"prediction_rows": merge(args.out)}))


if __name__ == "__main__":
    import sys
    if "--experiment" not in sys.argv:
        sys.argv.extend(["--experiment", 'e2000fs_feat30_lognormal_nll'])
    main()
